struct AuthMiddleware: AsyncMiddleware {
    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        guard let token = request.headers.bearerAuthorization, await tokens.isValid(token) else {
            throw Abort(.unauthorized)               // veto: the chain stops here
        }
        return try await next.respond(to: request)   // downstream chain
    }
}

app.middleware.use(AuthMiddleware())
